export function linearBugMessages(event, teams) {
  return [
    {
      role: "system",
      content: "I need you to classify a bug ticket and tell me which team should work on it",
    },
    {
      role: "system",
      content:
        "All possible teams will be described in the following format: [Teamname][Areas of responsibility] ",
    },
    { role: "system", content: "The possible teams are the following:\n " + teams },
    {
      role: "system",
      content:
        "This is the bug that we're trying to classify:\nTitle: " +
        event.title +
        "\nDescription: " +
        event.description,
    },
    { role: "user", content: "Which team should work on this bug?" },
    {
      role: "system",
      content:
        "Do not respond with anything else than the name of the team from the list you were given",
    },
  ];
}

export default function prepareLinearBug({
  body,
  sourceTeamId,
  triageStateId,
  bugLabelId,
  teams,
  slackChannel,
  recoveryKey,
}) {
  for (const [name, value] of Object.entries({
    sourceTeamId,
    triageStateId,
    bugLabelId,
    teams,
    slackChannel,
  }))
    if (typeof value !== "string" || !value.trim()) throw new Error("Configure " + name + ".");
  if (
    !body ||
    typeof body !== "object" ||
    Array.isArray(body) ||
    body.type !== "Issue" ||
    !body.data ||
    typeof body.data !== "object" ||
    Array.isArray(body.data)
  )
    throw new Error("A Linear Issue event is required.");
  if (
    typeof body.webhookTimestamp === "number" &&
    recoveryKey !== "triage:" + body.data?.id + ":" + body.webhookTimestamp
  ) {
    const timestamp = Math.floor(body.webhookTimestamp),
      seconds = timestamp > 1e10 ? Math.floor(timestamp / 1000) : timestamp;
    if (!Number.isFinite(seconds) || Math.abs(Math.floor(Date.now() / 1000) - seconds) > 60)
      throw new Error("The Linear event timestamp is outside the source one-minute window.");
  }
  const data = body.data,
    teamId = data.team?.id ?? data.teamId,
    stateId = data.state?.id ?? data.stateId,
    labelIds = Array.isArray(data.labels)
      ? data.labels.map((x) => x?.id)
      : Array.isArray(data.labelIds)
        ? data.labelIds
        : [];
  const eligible =
    teamId === sourceTeamId &&
    typeof data.description === "string" &&
    !data.description.includes("Add a description here") &&
    stateId === triageStateId &&
    labelIds.includes(bugLabelId);
  if (eligible && (typeof data.id !== "string" || !data.id || typeof data.title !== "string"))
    throw new Error("The selected bug lacks its issue ID or title.");
  const messages = eligible ? linearBugMessages(data, teams) : [];
  return {
    eligible,
    event: body,
    slackChannel,
    messages,
    prompt: messages.map((m) => m.role.toUpperCase() + ":\n" + m.content).join("\n\n"),
  };
}

