export default function planLinearBugTeam({ classification, teams, event }) {
  if (typeof classification !== "string" || !classification.trim())
    throw new Error("The model did not return a team name.");
  if (
    !Array.isArray(teams) ||
    teams.some(
      (team) => !team || typeof team.id !== "string" || !team.id || typeof team.name !== "string",
    )
  )
    throw new Error("Linear did not return a complete team list.");
  const issueId = event?.data?.id;
  if (typeof issueId !== "string" || !issueId) throw new Error("Missing source issue ID.");
  if (classification === "Other") return { route: "notify", issueId, teamId: null, classification };
  const selected = teams.find((team) => team.name === classification);
  if (!selected) throw new Error("The exact returned team name was not found in Linear.");
  return { route: "move", issueId, teamId: selected.id, classification };
}

