export function confirmedLinearMove({ issue, issueId, teamId, classification }) {
  if (!issue || issue.id !== issueId || issue.team?.id !== teamId)
    throw new Error(
      "Linear did not confirm the requested team move; inspect the issue before replay.",
    );
  return { result: { status: "moved", issueId, teamId, classification, issue } };
}
export function confirmedLinearFallback({
  ts,
  channelId,
  expectedChannelId,
  issueId,
  classification,
}) {
  if (typeof ts !== "string" || !ts || channelId !== expectedChannelId)
    throw new Error(
      "Slack did not confirm the fallback notification; inspect the channel before replay.",
    );
  return {
    result: { status: "notified", issueId, classification, notification: { ts, channelId } },
  };
}

export default function (input) {
  return confirmedLinearMove(input);
}

