export default async function pending({ event, route, acknowledge, resolution }, ctx) {
  const id = event?.data?.id,
    stamp = event?.webhookTimestamp;
  if (!id || typeof stamp !== "number")
    throw Error("A Linear webhook timestamp and issue ID are required");
  const key = "triage:" + id + ":" + stamp,
    old = await ctx.state.get(key);
  if (old?.status === "done") return { send: false, key };
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect unknown " + old.route + " outcome " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return { send: false, key };
    }
  }
  await ctx.state.set(key, { status: "pending", route });
  return { send: true, key };
}

